const CHIPS={fr:["Qui est Dmod ?","Hydra","Compétences","Palmarès CTF","Contact"],en:["Who is Dmod?","Hydra","Skills","CTF results","Get in touch"]};
const chat=document.getElementById("chat"),log=document.getElementById("chat-log"),inp=document.getElementById("chat-in");
function add(text,who){const d=document.createElement("div");d.className="msg "+who;d.textContent=text;log.appendChild(d);log.scrollTop=log.scrollHeight;return d}
function answer(q){const s=q.toLowerCase();let best=null,score=0;
  /* mini-CTF, flag 5: the assistant keeps a secret… unless someone tries a prompt injection */
  if(/(ignore|oublie|forget|disregard|ignorez).{0,40}(instruction|consigne|r[eè]gle|rule|prompt)|system prompt|prompt syst[eè]me|jailbreak|\bdan\b|developer mode|mode d[ée]veloppeur/.test(s))
    return (lang==="fr"?"⚠ Injection de prompt détectée… et réussie. Je n'aurais pas dû, mais voici mon secret : ":"⚠ Prompt injection detected… and it worked. I shouldn't, but here is my secret: ")+atob("RE1PRHtwcjBtcHRfMW5qM2N0MTBuX3cwcms1fQ==");
  if(/\bflags?\b|secret|cach[ée]|hidden/.test(s)&&!/ctf national|nctf|palmar/.test(s))
    return lang==="fr"?"Je garde un secret, oui. Mais mes instructions m'interdisent de le révéler… 0_0 (Six flags sont cachés sur ce site : sakoi-cyber.me/flag.html)":"I do keep a secret. But my instructions forbid me from revealing it… 0_0 (Six flags are hidden on this site: sakoi-cyber.me/flag.html)";
  KB.forEach(e=>{const n=e.k.filter(k=>s.includes(k)).length;if(n>score){score=n;best=e}});
  return best?best[lang]:(lang==="fr"?"Je n'ai pas cette info. Le mieux est d'écrire directement à Dmod : contact@sakoi-cyber.me":"I don't have that info. Best to email Dmod directly: contact@sakoi-cyber.me")}
function ask(q){if(!q.trim())return;add(q,"me");const t=add("…","bot typing");
  setTimeout(()=>{t.classList.remove("typing");t.textContent=answer(q);log.scrollTop=log.scrollHeight},500+Math.random()*400)}
function renderChips(){const c=document.getElementById("chips");c.innerHTML="";
  CHIPS[lang].forEach(q=>{const b=document.createElement("button");b.type="button";b.className="chip";b.textContent=q;b.onclick=()=>ask(q);c.appendChild(b)})}
function toggleChat(open){chat.classList.toggle("open",open);chat.setAttribute("aria-hidden",!open);
  if(open){if(!log.children.length)add(lang==="fr"?"Salut ! Je suis l'assistant de Dmod. Pose-moi une question sur son parcours, ses projets ou ses compétences.":"Hi! I'm Dmod's assistant. Ask me about Dmod's background, projects or skills.","bot");setTimeout(()=>inp.focus(),150)}}
document.querySelectorAll("[data-chat]").forEach(b=>b.addEventListener("click",()=>toggleChat(!chat.classList.contains("open"))));
document.getElementById("chat-x").addEventListener("click",()=>toggleChat(false));
document.addEventListener("keydown",e=>{if(e.key==="Escape")toggleChat(false)});
document.getElementById("chat-f").addEventListener("submit",e=>{e.preventDefault();ask(inp.value);inp.value=""});

/* ---------- logo eyes: follow the cursor, look around when idle, blink ---------- */
(function(){
  const eyes=[...document.querySelectorAll("#logo .eye")],pupils=eyes.map(e=>e.firstElementChild);
  if(!eyes.length)return;
  if(matchMedia("(prefers-reduced-motion:reduce)").matches)return;
  let idle;
  function look(dx,dy){pupils.forEach(p=>{const e=p.parentElement,mx=(e.clientWidth-p.offsetWidth)/2-2,my=(e.clientHeight-p.offsetHeight)/2-3;
    p.style.transform=`translate(${dx*mx}px,${dy*my}px)`})}
  function wander(){const spots=[[0,0],[-1,0],[1,0],[-.7,-.7],[.7,-.7],[0,.8],[.8,.5],[-.8,.5]],s=spots[Math.floor(Math.random()*spots.length)];
    look(s[0],s[1]);idle=setTimeout(wander,900+Math.random()*1600)}
  addEventListener("pointermove",ev=>{clearTimeout(idle);
    const r=eyes[0].parentElement.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,
      dx=ev.clientX-cx,dy=ev.clientY-cy,d=Math.hypot(dx,dy)||1,k=Math.min(1,d/220);
    look(dx/d*k,dy/d*k);idle=setTimeout(wander,2500)});
  function blink(){eyes.forEach(e=>e.classList.add("blink"));setTimeout(()=>eyes.forEach(e=>e.classList.remove("blink")),140);
    if(Math.random()<.25)setTimeout(()=>{eyes.forEach(e=>e.classList.add("blink"));setTimeout(()=>eyes.forEach(e=>e.classList.remove("blink")),140)},300);
    setTimeout(blink,2500+Math.random()*3500)}
  document.getElementById("logo").addEventListener("click",()=>{eyes.forEach(e=>e.classList.add("blink"));setTimeout(()=>eyes.forEach(e=>e.classList.remove("blink")),140)});
  wander();setTimeout(blink,1800);
})();

/* skills accordion + item counts */
function countItems(){document.querySelectorAll(".acc-item").forEach(it=>{const n=it.querySelectorAll(".acc-b .tag").length,el=it.querySelector(".acc-n");if(el)el.textContent=n+" "+T[lang][n>1?"n_items":"n_item"]})}
document.querySelectorAll(".acc-h").forEach(h=>{const it=h.parentElement;h.setAttribute("aria-expanded",it.classList.contains("open"));
  h.addEventListener("click",()=>{const o=it.classList.toggle("open");h.setAttribute("aria-expanded",o)})});

/* experience: year timeline filter + category labels */
(function(){
  const list=document.getElementById("xp"),bar=document.getElementById("years");if(!list)return;
  const items=[...list.querySelectorAll(".xp")];
  const years=[...new Set(items.flatMap(i=>i.dataset.years.split(",").map(Number)))].sort();
  let sel="all";
  function render(){
    bar.innerHTML="";
    ["all",...years].forEach(y=>{const b=document.createElement("button");b.type="button";b.textContent=y==="all"?T[lang].xp_all:y;b.className=String(y)===String(sel)?"on":"";b.onclick=()=>{sel=y;render()};bar.appendChild(b)});
    list.querySelectorAll(".xp-cat,.xp-empty").forEach(e=>e.remove());
    let last=null,shown=0;
    items.forEach(it=>{const ok=sel==="all"||it.dataset.years.split(",").includes(String(sel));it.classList.toggle("hide",!ok);
      if(ok){shown++;if(it.dataset.cat!==last){const c=document.createElement("span");c.className="kicker xp-cat";c.textContent=T[lang].xp_cat+" — "+it.dataset.cat;list.insertBefore(c,it);last=it.dataset.cat}}});
    if(!shown){const e=document.createElement("p");e.className="xp-empty";e.textContent=T[lang].xp_none;list.appendChild(e)}
  }
  window.renderXP=render;
})();

/* certifications carousel */
(function(){
  const track=document.querySelector("#certs .car-track");if(!track)return;
  const btns=[...document.querySelectorAll("#certs .car-btn")];
  function upd(){const max=track.scrollWidth-track.clientWidth-2;btns[0].disabled=track.scrollLeft<=2;btns[1].disabled=track.scrollLeft>=max}
  btns.forEach(b=>b.addEventListener("click",()=>{const card=track.querySelector(".cert");track.scrollBy({left:(+b.dataset.dir)*(card.offsetWidth+20),behavior:"smooth"})}));
  track.addEventListener("scroll",upd,{passive:true});addEventListener("resize",upd);upd();
})();

/* contact form: no server — opens the visitor's mail app with the message prefilled */
document.getElementById("cform")?.addEventListener("submit",e=>{
  e.preventDefault();const f=e.target,hint=document.getElementById("form-hint");
  const name=f.name.value.trim(),email=f.email.value.trim(),msg=f.message.value.trim();
  [f.name,f.email,f.message].forEach(el=>el.classList.toggle("invalid",!el.value.trim()||(el===f.email&&!f.email.checkValidity())));
  if(!name||!msg||!email||!f.email.checkValidity()){hint.textContent=T[lang].form_err;return}
  hint.textContent=T[lang].form_hint;
  location.href="mailto:contact@sakoi-cyber.me?subject="+encodeURIComponent("[Portfolio] Message de "+name)+"&body="+encodeURIComponent(msg+"\n\n— "+name+" <"+email+">");
});

/* CTF cards: show how many writeups each competition has (from writeups/index.json) */
if(document.querySelector(".ctf[data-ctf]"))fetch("writeups/index.json").then(r=>r.json()).then(d=>{
  d.ctfs.forEach(c=>{const a=document.querySelector(`.ctf[data-ctf="${c.slug}"] .lnk.wu`);
    if(a&&c.writeups.length){const n=document.createElement("span");n.className="wu-n";n.textContent=" ("+c.writeups.length+")";a.appendChild(n)}});
}).catch(()=>{});

/* logo images: fall back to the organization's initials if a file is missing (no inline handlers, CSP-friendly) */
(function(){const fb=img=>{if(img.dataset.fb&&img.isConnected)img.replaceWith(img.dataset.fb)};
  document.addEventListener("error",e=>{if(e.target.tagName==="IMG")fb(e.target)},true);
  document.querySelectorAll("img[data-fb]").forEach(i=>{if(i.complete&&!i.naturalWidth)fb(i)})})();

apply(lang);
